using System.IO;using System.Reflection;using System.Security.Cryptography;using System.Text.Json;using System.Windows;using System.Windows.Controls;using System.Windows.Input;using System.Windows.Media;using System.Windows.Media.Imaging;using RAWSelectionAssistant.Core.Services.Projects;using RAWSelectionAssistant.Services;using RAWSelectionAssistant.ViewModels;using RAWSelectionAssistant.Views;using static RAWSelectionAssistant.WpfTests.RuntimeCorrectionWpfTests;
namespace RAWSelectionAssistant.WpfTests;
[TestClass][DoNotParallelize]public class R55InteractionFixTests
{
 static string Root{get{var p=Environment.GetEnvironmentVariable("KITAO_R55_FIX_ROOT")??Path.Combine(Path.GetTempPath(),"r55-fix-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(p);return p;}}
 static BitmapSource Image(int w,int h,int offset=0){var rgb=new byte[w*h*3];for(int y=0;y<h;y++)for(int x=0;x<w;x++){int i=(y*w+x)*3;rgb[i]=(byte)((x+offset)%251);rgb[i+1]=(byte)(y%251);rgb[i+2]=(byte)((x+y)%251);}var b=BitmapSource.Create(w,h,96,96,PixelFormats.Rgb24,null,rgb,w*3);b.Freeze();return b;}
 static async Task<ReferenceColorWorkspaceViewModel> Workspace(int count=3){EnsureTestApplication();var root=Path.Combine(Root,Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var vm=new ReferenceColorWorkspaceViewModel(new CompanyViewingMeasurementsTests.Dialogs());for(int i=0;i<count;i++){var path=Path.Combine(root,i+".png");var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(Image(240,160,i*30)));using(var f=File.Create(path))encoder.Save(f);await vm.LoadTargetAsync(path);await vm.CreateR53VariantAsync(true);vm.ActiveTarget!.IsSelected=true;}vm.PinSelectedViewingVariants();await vm.PrepareViewingTableAsync();return vm;}
 static void Layout(FrameworkElement view){view.Measure(new Size(1366,768));view.Arrange(new Rect(0,0,1366,768));view.UpdateLayout();}
 static void Click(Button button)=>button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
 static async Task Turn()=>await System.Windows.Threading.Dispatcher.Yield(System.Windows.Threading.DispatcherPriority.Background);
 [TestMethod]public Task RealGenerateButtonCloseSidebarContinuesThenSelectOnceAndFrozenSourceComparison()=>RunSta(async()=>{new ViewingPreferences().Save();using var vm=await Workspace();var view=new StudioViewingTableView(vm);Layout(view);var source=vm.ViewingFrames[0];view.SelectForTest(source);view.OpenFilmSidebarForTest();await view.PreflightForTest();Assert.IsTrue(view.GenerateEnabled);var started=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var complete=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);vm.ViewingFilmBeforeCommit=async token=>{started.TrySetResult();await complete.Task;};var count=vm.Targets.Sum(t=>t.EditVersions.Count);Click(view.GenerateButton);await started.Task;Assert.IsTrue(vm.IsFilmTaskRunning);Click(view.SidebarToggleButton);Assert.IsTrue(vm.IsFilmTaskRunning);Click(view.SidebarToggleButton);Assert.AreEqual(vm.FilmTaskStatus,view.FilmPanelStatus);complete.SetResult();await view.GenerateWork;var result=vm.LastViewingFilmResult;Assert.IsNotNull(result);Assert.AreEqual(count+1,vm.Targets.Sum(t=>t.EditVersions.Count));Assert.AreEqual(result,view.SelectedVariant);var other=vm.ViewingFrames.First(f=>f.Item.VariantId!=result&&f.Item.VariantId!=source.Item.VariantId);view.SelectForTest(other);await vm.PrepareViewingTableAsync();Assert.AreEqual(other.Item.VariantId,view.SelectedVariant);vm.RemoveViewingItem(source.Item.TargetId,source.Item.VariantId);await view.CompareResultAsync();CollectionAssert.AreEqual(new[]{source.Item.VariantId,result.Value},view.LastComparisonVariants.ToArray());view.Close();new ViewingPreferences().Save();});
 [TestMethod]public Task RealTaskExplicitCancelHasNoPartialVariant()=>RunSta(async()=>{using var vm=await Workspace(1);var view=new StudioViewingTableView(vm);Layout(view);view.SelectForTest(vm.ViewingFrames[0]);view.OpenFilmSidebarForTest();await view.PreflightForTest();var started=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var finish=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);vm.ViewingFilmBeforeCommit=async t=>{started.TrySetResult();await finish.Task;};int count=vm.Targets[0].EditVersions.Count;Click(view.GenerateButton);await started.Task;Click(view.FilmCancelButton);finish.SetResult();await view.GenerateWork;Assert.AreEqual(count,vm.Targets[0].EditVersions.Count);Assert.IsNull(vm.LastViewingFilmResult);StringAssert.Contains(vm.FilmTaskStatus,"取消");view.Close();});
 [TestMethod]public Task NonAdjacentSelectionComparisonAndInvalidCountsHaveVisibleFeedback()=>RunSta(async()=>{using var vm=await Workspace(4);var view=new StudioViewingTableView(vm);Layout(view);var ids=vm.ViewingTable.Items.OrderBy(i=>i.Z).Select(i=>i.VariantId).ToArray();view.SelectVariantsForTest(ids[0],ids[2]);await view.CompareAsync();CollectionAssert.AreEqual(new[]{ids[0],ids[2]},view.LastComparisonVariants.ToArray());view.SelectVariantsForTest(ids[0],ids[1],ids[3]);await view.CompareAsync();Assert.IsTrue(view.FeedbackVisible);StringAssert.Contains(view.VisibleStatus,"两张");view.SelectVariantsForTest();await view.CompareAsync();Assert.IsTrue(view.FeedbackVisible);view.Close();});
 [TestMethod]public Task PauseEachSlidePhaseRejectsLateImageAndSoundAndSpaceRepeat()=>RunSta(async()=>{new ViewingPreferences(Sound:true,ReduceMotion:false).Save();foreach(var phase in new[]{"Loading","Black","Arriving"}){using var vm=await Workspace(3);var view=new StudioViewingTableView(vm);Layout(view);view.DetailRenderer=(i,e,t)=>Task.FromResult(vm.ViewingFrames.First(f=>f.Item.VariantId==i.VariantId).Image);view.AnimationAllowed=()=>true;view.SlideDelay=(_,_)=>Task.CompletedTask;await view.StartSlideshowForTest();await Turn();var first=view.PresentedSlide;Assert.IsNotNull(first);var signal=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var gate=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);view.SlidePhaseObserved=p=>{if(p==phase)signal.TrySetResult();};if(phase=="Loading")view.DetailRenderer=async(i,e,t)=>{signal.TrySetResult();await gate.Task;return vm.ViewingFrames.First(f=>f.Item.VariantId==i.VariantId).Image;};else view.SlideDelay=(time,token)=>view.SlidePhase==phase?gate.Task:Task.CompletedTask;var work=view.ShowSlideAsync(1);await signal.Task;int sounds=view.SlideSoundCount;view.PauseSlideshowForTest();var presented=view.PresentedSlide;var content=view.DetailContent;gate.SetResult();await work;Assert.IsTrue(view.SlideshowPaused);Assert.AreEqual(presented,view.PresentedSlide);Assert.AreSame(content,view.DetailContent);Assert.AreEqual(sounds,view.SlideSoundCount);view.DetailRenderer=(i,e,t)=>Task.FromResult(vm.ViewingFrames.First(f=>f.Item.VariantId==i.VariantId).Image);view.SlideDelay=(_,_)=>Task.CompletedTask;await view.ShowSlideAsync(1);Assert.IsTrue(view.SlideshowPaused,"Manual next remains paused");view.ReleaseSpaceForTest();view.HandleShortcut(Key.Space,ModifierKeys.None);bool after=view.SlideshowPaused;view.HandleShortcut(Key.Space,ModifierKeys.None,true);Assert.AreEqual(after,view.SlideshowPaused);view.ReleaseSpaceForTest();view.HandleShortcut(Key.V,ModifierKeys.None);Assert.IsFalse(view.SlideshowPaused);view.Close();}new ViewingPreferences().Save();});
 [TestMethod]public Task RealUniformImageMappingLandscapePortraitSquareRotatedViewport()=>RunSta(async()=>{using var vm=await Workspace(1);var item=vm.ViewingTable.Items.Single();foreach(var size in new[]{new Size(400,100),new Size(100,400),new Size(200,200)}){vm.ReleaseViewing();var image=Image((int)size.Width,(int)size.Height);vm.ViewingRenderOverride=(_,_,_)=>Task.FromResult(image);vm.SetViewingPlacement(item.TargetId,item.VariantId,300,240,1.7,37);vm.SetViewingViewport(.65,70,-20);await vm.PrepareViewingTableAsync();var view=new StudioViewingTableView(vm);Layout(view);await view.RefreshAsync();Layout(view);view.SelectForTest(vm.ViewingFrames[0]);var matrix=view.SelectedPixelMatrixForTest(image);var known=new Point(image.PixelWidth*.3,image.PixelHeight*.6);var pointer=matrix.Transform(known);Assert.IsTrue(view.MapLoupeForTest(pointer,image,out var actual));Assert.AreEqual(known.X,actual.X,1e-7);Assert.AreEqual(known.Y,actual.Y,1e-7);var outside=matrix.Transform(new Point(-10,image.PixelHeight*.5));Assert.IsFalse(view.MapLoupeForTest(outside,image,out _));var lens=ViewingImageMapping.LoupeMatrix(matrix,pointer,248,8,out var mag);var center=lens.Transform(known);Assert.AreEqual(124,center.X,1e-7);Assert.AreEqual(124,center.Y,1e-7);Assert.AreEqual(Math.Sqrt(lens.M11*lens.M11+lens.M12*lens.M12),Math.Sqrt(lens.M21*lens.M21+lens.M22*lens.M22),1e-9);view.Close();}});
 [TestMethod]public Task LostCaptureFinalizesOnceStableOrderingAndCrossProjectHistoryReset()=>RunSta(async()=>{using var vm=await Workspace(4);var view=new StudioViewingTableView(vm);Layout(view);var item=vm.ViewingTable.Items[0];var before=JsonSerializer.Serialize(vm.ViewingTable);view.BeginGestureForTest(item);vm.SetViewingPlacement(item.TargetId,item.VariantId,500,410,1.2,27);var card=view.CardForTest(item.VariantId)!;card.RaiseEvent(new MouseEventArgs(Mouse.PrimaryDevice,0){RoutedEvent=Mouse.LostMouseCaptureEvent});Assert.IsFalse(vm.ViewingGestureActive);vm.UndoViewing();Assert.AreEqual(before,JsonSerializer.Serialize(vm.ViewingTable));var ids=vm.ViewingTable.Items.OrderBy(i=>i.Z).Select(i=>i.VariantId).ToArray();vm.OrderViewingSelection(new[]{ids[2],ids[0]},true);CollectionAssert.AreEqual(new[]{ids[1],ids[3],ids[0],ids[2]},vm.ViewingTable.Items.OrderBy(i=>i.Z).Select(i=>i.VariantId).ToArray());var file=Path.Combine(Root,Guid.NewGuid()+".ptstudio.json");using(var other=await Workspace(1))await other.SaveSessionAsync(file);await vm.LoadSessionAsync(file);Assert.IsFalse(vm.CanUndoViewing);Assert.IsFalse(vm.ViewingGestureActive);Assert.IsNull(vm.LastViewingFilmCompletion);view.Close();});
 [TestMethod]public Task SidebarSourcePreflightAndFilterFollowCurrentSelection()=>RunSta(async()=>{using var vm=await Workspace(2);var view=new StudioViewingTableView(vm);Layout(view);view.SelectForTest(vm.ViewingFrames[0]);view.OpenFilmSidebarForTest();await view.PreflightForTest();var second=vm.ViewingFrames[1];view.SelectForTest(second);Assert.AreEqual(second.Item.FrozenVariant.Name,view.FilmSourceName);await view.PreflightForTest();Assert.IsTrue(view.GenerateEnabled);view.FixedFilter=1;await vm.PrepareViewingTableAsync();Assert.AreEqual(1,view.FixedFilter);view.Close();});
 [TestMethod]public Task LampWholeRangeKeepsComparisonStillAndEncodedOutputIdentical()=>RunSta(async()=>{using var vm=await Workspace(2);var view=new StudioViewingTableView(vm);Layout(view);var frame=vm.ViewingFrames[0];view.SelectForTest(frame);var version=frame.Item.FrozenVariant;var path=vm.Targets.Single(t=>t.Id==frame.Item.TargetId).Path;var first=await vm.Editor.ProcessForExportAsync(path,version.Look,version.Film,CancellationToken.None,version.Stack);var compareBefore=PixelHash(frame.Image);await vm.PrepareR53SharedComparisonAsync([vm.ActiveTarget!.ActiveEditVersionId!.Value],new StudioStillSnapshot(Guid.NewGuid(),"test",Png64(frame.Image),version.Stack){SourceTargetId=frame.Item.TargetId,SourceVersionId=frame.Item.VariantId,SourceHash=frame.Item.SourceHash,InputDomain="EncodedSrgbRasterStack"});var comparison=vm.R53CompareFrames.Select(f=>PixelHash(f.Image)).ToArray();Assert.IsTrue(vm.CaptureR54Still(),vm.StatusText);var actualStill=PixelHash(ReferenceColorWorkspaceViewModel.R54StillImage(vm.R54Stills.Last()));var stillBefore=Png64(frame.Image);var colors=new List<Color>();foreach(var level in new[]{.1,.5,1,1.2,1.6}){view.SetBrightnessForTest(level);colors.Add(view.BoardColor);}Assert.AreNotEqual(colors[2],colors[3]);Assert.AreNotEqual(colors[3],colors[4]);for(int i=1;i<colors.Count;i++)Assert.IsTrue(colors[i].R+colors[i].G+colors[i].B>colors[i-1].R+colors[i-1].G+colors[i-1].B);view.ToggleLampForTest();var second=await vm.Editor.ProcessForExportAsync(path,version.Look,version.Film,CancellationToken.None,version.Stack);Assert.AreEqual(PixelHash(first),PixelHash(second));Assert.AreEqual(compareBefore,PixelHash(frame.Image));Assert.AreEqual(stillBefore,Png64(frame.Image));Assert.IsTrue(vm.CaptureR54Still(),vm.StatusText);Assert.AreEqual(actualStill,PixelHash(ReferenceColorWorkspaceViewModel.R54StillImage(vm.R54Stills.Last())));CollectionAssert.AreEqual(comparison,vm.R53CompareFrames.Select(f=>PixelHash(f.Image)).ToArray());vm.CloseR53VariantComparison();await vm.PrepareR53SharedComparisonAsync([vm.ActiveTarget!.ActiveEditVersionId!.Value],new StudioStillSnapshot(Guid.NewGuid(),"test",Png64(frame.Image),version.Stack){SourceTargetId=frame.Item.TargetId,SourceVersionId=frame.Item.VariantId,SourceHash=frame.Item.SourceHash,InputDomain="EncodedSrgbRasterStack"});CollectionAssert.AreEqual(comparison,vm.R53CompareFrames.Select(f=>PixelHash(f.Image)).ToArray());var bytesA=Png64(first);var bytesB=Png64(second);Assert.AreEqual(bytesA,bytesB);await File.WriteAllTextAsync(Path.Combine(Root,"LAMP_ISOLATION.json"),JsonSerializer.Serialize(new{proxy=compareBefore,output=PixelHash(first),comparisonStable=true,stillStable=true,encodedPngStable=true,colors=colors.Select(c=>c.ToString()).ToArray()}));view.Close();});
 static string PixelHash(BitmapSource image){var rgb=new FormatConvertedBitmap(image,PixelFormats.Bgra32,null,0);var bytes=new byte[rgb.PixelWidth*rgb.PixelHeight*4];rgb.CopyPixels(bytes,rgb.PixelWidth*4,0);return Convert.ToHexString(SHA256.HashData(bytes));}
 static string Png64(BitmapSource image){var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(image));using var stream=new MemoryStream();png.Save(stream);return Convert.ToBase64String(stream.ToArray());}

 [TestMethod]public Task ExportPinnedOpticalResponseForTwoReferenceComparison()=>RunSta(async()=>{EnsureTestApplication();var samples=new List<object>();for(int i=0;i<=150;i++){double b=.1+i*.01;samples.Add(new{brightness=b,panelWhite=RAWSelectionAssistant.Core.Services.Projects.LightTablePort.LightResponse.PanelWhite(b,0),unlit=StudioViewingTableView.DisplayPanelColor(false,b).ToString(),lit=StudioViewingTableView.DisplayPanelColor(true,b).ToString()});}var clocks=Enumerable.Range(0,201).Select(i=>new{time=i*.01,response=RAWSelectionAssistant.Core.Services.Projects.LightTablePort.LightResponse.Sample(i*.01,true)}).ToArray();await File.WriteAllTextAsync(Path.Combine(Root,"OPTICAL_SAMPLES.json"),JsonSerializer.Serialize(new{samples,clocks,domain="SDR board only; proxy image color bytes untouched; encoded 8-bit D65 display material",version="R55BoardResponse2"},new JsonSerializerOptions{WriteIndented=true}));});

 [TestMethod]public Task SelectingLoadedCardKeepsProgressiveWorkButDoesNotStealSelection()=>RunSta(async()=>{using var vm=await Workspace(3);var images=vm.ViewingFrames.ToDictionary(f=>f.Item.VariantId,f=>f.Image);var first=vm.ViewingTable.Items[0];var gate=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var started=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var view=new StudioViewingTableView(vm);Layout(view);CancellationToken pending=default;int calls=0;vm.ViewingRenderOverride=async(i,e,t)=>{if(++calls==2){pending=t;started.TrySetResult();await gate.Task;}return images[i.VariantId];};var work=view.RefreshAsync();await started.Task;view.SelectForTest(vm.ViewingFrames.Single());Assert.IsFalse(pending.IsCancellationRequested);gate.SetResult();await work;Assert.AreEqual(3,vm.ViewingFrames.Count);Assert.AreEqual(first.VariantId,view.SelectedVariant);view.Close();});

}
